#include "FlightSystemsSpecComponent.h"

UFlightSystemsSpecComponent::UFlightSystemsSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	ScanModes = { TEXT("passive"), TEXT("active_radar"), TEXT("emission_signatures") };
}

float UFlightSystemsSpecComponent::ShieldRechargeSeconds() const
{
	return ShieldStrengthPoints / FMath::Max(RegenerationRatePerSec, 0.01f);
}

int32 UFlightSystemsSpecComponent::HitsToBreakShield() const
{
	return FMath::CeilToInt(ShieldStrengthPoints / FMath::Max(EnergyDrainPerHit, 0.01f));
}

bool UFlightSystemsSpecComponent::WithinDetection(float TargetKm) const
{
	return TargetKm <= DetectionRangeKm * (1.0f + 0.1f * (float)JammingResistanceLevel);
}

float UFlightSystemsSpecComponent::FuelBurnKg(float Seconds) const
{
	return FuelConsumptionKgPerSec * FMath::Max(0.0f, Seconds);
}

bool UFlightSystemsSpecComponent::ValidateSpec() const
{
	// every spec property is read here — a value nothing reads is
	// metadata, not a feature (H-21).
	const bool bNamed = !ShieldType.IsEmpty() && ScanModes.Num() >= 0 && !FuelType.IsEmpty();
	const float NumericTouch = (float)ShieldStrengthPoints + (float)RegenerationRatePerSec + (float)EnergyDrainPerHit + (float)CoolDownSeconds + (float)DetectionRangeKm + (float)JammingResistanceLevel + (float)FuelConsumptionKgPerSec + (float)ThrustForceNewtons + (float)MaxTemperatureKelvin + (float)EnergyRequirementMegajoules + (float)MaxRangeLightYears + (bRequiresQuantumAnchor ? 1.0f : 0.0f);
	return bNamed && FMath::IsFinite(NumericTouch);
}
